-- Event landing template: seed the Freedom Ride Poker Run.
-- The renderer (src/api/render_event_landing.js) is generic; everything below is DATA.
-- Idempotent. Apply AFTER the renderer is deployed:
--   npx wrangler d1 execute companionscpas --remote --file db/migrations/20261025_event_landing_freedom_ride.sql

-- 1) The event's content lives on its campaign (config_json.event).
UPDATE fundraising_campaigns
SET config_json = json_set(COALESCE(NULLIF(config_json, ''), '{}'), '$.event', json('{"kicker":"Sat · Nov 7","where_line":"Bossier City → Shreveport","title_accent":"Ride","subtitle":"Poker Run","tagline":"Ride with purpose. Support our veterans. Save lives.","intro":"One day, six stops, one big finish. A poker run benefiting Companions of CPAS and the revival of Paws for Patriots.","ornament":"stars","facts":["$20 driver","$10 passenger","All vehicles welcome"],"secondary_label":"See the route","cta_label":"Deal me in","schedule_title":"The day at a glance","schedule":[{"time":"9–10 AM","label":"Registration","where":"3 State Harley-Davidson, Bossier City"},{"time":"10:30 AM","label":"KSU","where":"Kickstands up. The ride begins."},{"time":"12 PM","label":"Doors open","where":"Seventh Tap Brewery, the finish line"},{"time":"3 PM","label":"Check-in","where":"Seventh Tap check-in starts no earlier than 3"},{"time":"4 PM","label":"Judging","where":"Then winners, then raffle winners"},{"time":"6 PM","label":"Music","where":"Music starts at Seventh Tap"}],"tickets_eyebrow":"Entry","tickets_title":"Pick your hand.","tickets_intro":"Every vehicle is welcome. Every entry puts $5 into the 50/50 pot, and every extra hand is another shot at it.","tickets":[{"key":"driver","label":"Driver","price_cents":2000,"note":"Your vehicle and your first hand. Cars, trucks, trikes and bikes are all welcome.","perk":"$5 goes into the 50/50 pot","cta":"Pay $20"},{"key":"passenger","label":"Passenger","price_cents":1000,"note":"Along for the ride, with a hand of your own.","perk":"$5 goes into the 50/50 pot","cta":"Pay $10"},{"key":"extra_hand","label":"Extra hand","price_cents":500,"note":"Play another hand to chase a better score.","perk":"Earns another 50/50 entry","cta":"Add $5"}],"pot":{"label":"The 50/50 pot","note":"$5 from each entry goes in. Each extra hand adds another entry. Additional donations are always welcome."},"stops_eyebrow":"The route","stops_title":"Six stops. One finish line.","stops_intro":"Every stop is a chance to draw a card and meet the mission. This is a suggested route, so keep each stop’s business hours in mind.","stops":[{"name":"3 State Harley-Davidson","address":"2225 Autoplex Dr, Bossier City, LA 71111","hours":"Registration 9–10 AM · KSU 10:30 AM","tag":"Start line"},{"name":"VFW Post","address":"1315 Northgate Rd, Bossier City, LA 71112","tag":"Paws for Patriots"},{"name":"Candyman Pet Lodge","address":"2580 Boggy Rd, Waskom, TX 75692","tag":"Why volunteer?"},{"name":"Caddo Parish Animal Shelter","address":"1500 Monty St, Shreveport, LA 71107","hours":"Closes at 2 PM","tag":"Why foster? · Tour the shelter"},{"name":"G&C Honda Shreveport","address":"2415 E 70th St, Shreveport, LA 71105","hours":"Closes at 3 PM","tag":"Lunch"},{"name":"Seventh Tap Brewery","address":"2640 Linwood Ave, Shreveport, LA 71103","hours":"Doors 12 PM · Check-in from 3 PM · Judging 4 PM · Music 6 PM","tag":"The finish line"}],"rules_eyebrow":"How the game works","rules_title":"The house rules.","rules":["Cards are drawn at the designated stops, one at a time, and laid face up on the table after you complete the stop’s task. You can’t pick up all your cards at one stop.","No duplicate cards. If you draw an identical card, draw again.","Playing more than one hand? Present a second Poker Run Tally Sheet Ticket and Tally Sheet to be marked before each card is drawn.","Ties are settled by a draw for high card. Riders must be present to receive any winnings.","All decisions of the judges are final."],"references":[{"eyebrow":"Highest to lowest","title":"Know your hand.","items":[{"name":"Royal Flush","desc":"10 through Ace, all one suit"},{"name":"Straight Flush","desc":"Five in a row, all one suit"},{"name":"Four of a Kind","desc":"Four cards of the same rank"},{"name":"Full House","desc":"Three of a kind plus a pair"},{"name":"Flush","desc":"Five cards of one suit"},{"name":"Straight","desc":"Five in a row, mixed suits"},{"name":"Three of a Kind","desc":"Three cards of the same rank"},{"name":"Two Pair","desc":"Two different pairs"},{"name":"Pair","desc":"Two cards of the same rank"},{"name":"High Card","desc":"No match? The highest card plays"}]}],"why":{"eyebrow":"Why we ride","quote":"This ride is about more than motorcycles, miles, great stops, and good times. It’s about coming together as a community to make a difference in the lives of animals and the people who need them most.","cards":[{"title":"Companions of CPAS","body":"Volunteer-powered rescue support helping dogs at Caddo Parish Animal Services receive medical care, transport pathways, and second chances."},{"title":"Paws for Patriots","body":"A program dedicated to the powerful bond between service dogs and the veterans they serve, and this ride helps bring it back to life."}]},"closing":{"title":"One mile, one paw, one life at a time.","body":"Ride, volunteer, or show up to cheer. And if you can’t make it, your gift still rides along.","cta":"Donate to the Freedom Ride"}}')),
    updated_at = datetime('now')
WHERE slug = 'freedom-ride-poker-run';

-- 2) A draft page for it. Publish from the dashboard when ready.
INSERT OR IGNORE INTO cms_pages
  (id, tenant_id, route_path, slug, title, status, seo_title, meta_description,
   page_type, template_key, nav_visible, nav_label, nav_placement, theme)
SELECT 'page_' || lower(hex(randomblob(8))), fc.tenant_id, '/freedom-ride', 'freedom-ride',
       'Freedom Ride Poker Run', 'draft',
       'Freedom Ride Poker Run | Companions of CPAS',
       'A poker run benefiting Companions of CPAS and the revival of Paws for Patriots. Saturday, November 7, Bossier City to Shreveport.',
       'standard', 'default', 0, 'Freedom Ride', 'more', 'plum_glass'
FROM fundraising_campaigns fc
WHERE fc.slug = 'freedom-ride-poker-run';

-- 3) One section: the template, pointed at the campaign.
INSERT OR IGNORE INTO cms_page_sections
  (id, tenant_id, page_route, section_key, section_type, heading, sort_order, is_visible, config_json)
SELECT 'sec_' || lower(hex(randomblob(8))), fc.tenant_id, '/freedom-ride', 'event', 'event_landing',
       'The Freedom Ride', 10, 1, json_object('campaign_id', fc.id)
FROM fundraising_campaigns fc
WHERE fc.slug = 'freedom-ride-poker-run';
